import{_ as t,o as n,c as o,a0 as a}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"1D Packing (BPP1D): Scope and Learning Path","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/bpp1d/index.md","filePath":"frameworks/bpp1d/index.md"}'),i={name:"frameworks/bpp1d/index.md"};function d(c,e,s,r,l,p){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="_1d-packing-bpp1d-scope-and-learning-path" tabindex="-1">1D Packing (BPP1D): Scope and Learning Path <a class="header-anchor" href="#_1d-packing-bpp1d-scope-and-learning-path" aria-label="Permalink to &quot;1D Packing (BPP1D): Scope and Learning Path&quot;">​</a></h1><p>Pack existing long items into length-limited containers, such as loading cut-to-length profiles. Each container type has length, weight capacity, cost and available stock; adjacent items may require spacing. BPP1D chooses packing compositions and produces physical placements you can inspect.</p><h2 id="essential-objects" tabindex="-1">Essential Objects <a class="header-anchor" href="#essential-objects" aria-label="Permalink to &quot;Essential Objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Business concept</th><th>API</th><th>Role</th><th>Key fields</th></tr></thead><tbody><tr><td>Item</td><td><code>Item</code></td><td>Input</td><td>Stable <code>id</code>, <code>length</code>, <code>weight</code>, exact <code>amount</code></td></tr><tr><td>Container type</td><td><code>BinType</code></td><td>Input</td><td>Length, weight capacity, <code>cost</code>, optional <code>inventory</code></td></tr><tr><td>Problem</td><td><code>PackingProblem</code></td><td>Input</td><td>Items, container types, <code>spacing</code>, <code>objective</code></td></tr><tr><td>Composition</td><td><code>PackingPattern</code></td><td>Intermediate</td><td>Container type ID and item counts, before coordinate expansion</td></tr><tr><td>Solve result</td><td><code>Bpp1dSolution</code></td><td>Output</td><td>Status/report, candidate completeness, column count, <code>packing</code></td></tr><tr><td>Physical packing</td><td><code>PackingResult</code></td><td>Output</td><td><code>plans</code>, free/tail intervals, material totals</td></tr><tr><td>Indicators</td><td><code>PackingKpi</code></td><td>Output</td><td>Container count, item count, consumed capacity length, tail length, utilization, cost</td></tr></tbody></table><p>Spacing applies only between adjacent items in the same container. There is no extra leading or trailing gap: packing n items introduces n−1 gaps.</p><div class="tip custom-block"><p class="custom-block-title">Units and Stock</p><p>Length and weight retain physical units. Kotlin converts compatible units through its adapter; the Rust lesson normalizes inputs to meters/kilograms. <code>inventory = null</code> (Kotlin) / <code>None</code> (Rust) means unlimited; <code>0</code> / <code>Some(0)</code> means unavailable.</p></div><h3 id="find-business-fields-in-the-result" tabindex="-1">Find Business Fields in the Result <a class="header-anchor" href="#find-business-fields-in-the-result" aria-label="Permalink to &quot;Find Business Fields in the Result&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What to read</th><th>Kotlin</th><th>Rust</th></tr></thead><tbody><tr><td>Candidate enumeration complete</td><td><code>solution.candidateComplete</code></td><td><code>solution.candidate_complete</code></td></tr><tr><td>Used containers</td><td><code>solution.packing.plans</code></td><td><code>plans</code> after <code>solution.packing.as_ref()</code></td></tr><tr><td>Container and type</td><td><code>plan.bin.id</code>, <code>plan.bin.type</code></td><td><code>plan.bin_id</code>, <code>plan.bin_type_id</code>; look up <code>context.problem().bin_types</code></td></tr><tr><td>Item interval</td><td><code>placement.itemId</code>, <code>start</code>, <code>start + length</code></td><td><code>placement.item_id</code>, <code>start</code>, <code>length</code></td></tr><tr><td>Tail/free intervals</td><td><code>packing.remnants</code> for tails; derive gaps from adjacent placements</td><td><code>packing.free_intervals</code>, including internal gaps and tails</td></tr><tr><td>Core KPIs</td><td><code>packing.kpi(Meter)</code></td><td><code>context.kpi(&amp;packing)</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Language-Specific Results</p><p>Kotlin exposes <code>packing</code> directly on success; Rust uses an <code>Option</code>, so inspect <code>report</code> when no feasible solution was returned. Both KPI fields <code>remnantLength</code> / <code>remnant_length</code> count tails only, excluding spacing. The generator&#39;s <code>complete</code> becomes the solution&#39;s candidate-completeness field; <strong>it does not by itself prove integer optimality</strong>.</p></div><h2 id="which-entry-point" tabindex="-1">Which Entry Point? <a class="header-anchor" href="#which-entry-point" aria-label="Permalink to &quot;Which Entry Point?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>Use it for</th><th>How to evaluate it</th></tr></thead><tbody><tr><td><code>Bpp1dMilp</code></td><td>Initial integration, small instances, or generated pools that fit a direct integer master</td><td>Establish correctness and runtime baselines; inspect completeness and column count</td></tr><tr><td><code>Bpp1dColumnGeneration</code></td><td>Inspecting LP pricing or comparing staged column activation</td><td>Compare runtime, column count and reports with the same data, generation budgets and backend</td></tr></tbody></table><p>Both entries currently generate a <strong>bounded finite candidate pool first</strong>. Column generation prices within that pool, and the final integer model uses the union of generated and initial columns. It does not bypass enumeration, so there is no universal item-count threshold for switching. Benchmark representative inputs.</p><p>Kotlin injects <code>ColumnGenerationSolver</code> and a numeric adapter into the constructor; Rust injects a solver callback into <code>solve</code>. See the <a href="./business-scenario.html#column-generation">second lesson&#39;s switching and budget example</a>.</p><h2 id="scope-boundaries" tabindex="-1">Scope Boundaries <a class="header-anchor" href="#scope-boundaries" aria-label="Permalink to &quot;Scope Boundaries&quot;">​</a></h2><ul><li>This models loading existing items. For material processing, production and over/underproduction, compare <a href="./../csp1d/">CSP1D</a>.</li><li>Candidate/node budgets can truncate enumeration; read candidate completeness with the report.</li><li>LP pricing termination and finite-pool optimality have different proof scopes from global integer optimality.</li><li>Tail repacking must revalidate the full plan, including global business rules.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">Setup</a>.</li><li>Follow <a href="./first-packing.html">your first 1D packing</a> through input, solving, placements and exact counts.</li><li>Add stock, cost and custom rules in the second lesson.</li><li>For custom models, consult the <a href="/ospf/guide/modeling-workflow.html">modeling workflow</a>.</li></ol><p>For LP, MILP, pricing and other algorithm terms, see the <a href="./../#terminology">terminology guide</a>.</p><h2 id="api-references" tabindex="-1">API References <a class="header-anchor" href="#api-references" aria-label="Permalink to &quot;API References&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp1d/README.md" target="_blank" rel="noreferrer">Kotlin API and extension interfaces</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp1d/README.md" target="_blank" rel="noreferrer">Rust API and extension interfaces</a></li><li><a href="/ospf/guide/solving-results.html">Understanding solve results</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./first-packing.html">Your First 1D Packing: Items, Gaps and Stock</a>. Then explore <a href="./business-scenario.html">container types, stock and cost</a> and the <a href="./../integration.html">business integration checks</a>.</p>',23)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
